  blueEnergyUse: number;
  blueSpeed: number;
  blueVision: number;
  blueCopyAt: number;
  blueEatTime: number;

  redEnergyUse: number;
  redSpeed: number;
  redVision: number;
  redContact: number;
  redCopyAt: number;
  redPauseTime: number;

  startTrees: number;
