    const p = this.next();
    this.tmp.set(o.color);
    p.alive = true;
    p.homing = false;
    p.x = o.x;
    p.y = o.y;
    p.z = o.z;
    p.vx = o.vx ?? 0;
    p.vy = o.vy ?? 0;
    p.vz = o.vz ?? 0;
    p.gravity = o.gravity ?? 0;
    p.drag = o.drag ?? 0;
    p.life = p.maxLife = o.life;
    p.size = o.size;
    p.grow = o.grow ?? 0;
    p.r = this.tmp.r;
    p.g = this.tmp.g;
    p.b = this.tmp.b;
    p.shape = o.shape ?? Shape.Dot;
  }

