  seek: "Heading for fruit",
  wait: "Waiting by a tree",
  eat: "Munching fruit",
  flee: "Dodging a red blob",
  crowd: "Making room",
  startled: "Scurrying off after a hug",
  hugged: "Being hugged",
  chase: "Chasing a blue blob",
  lurk: "Waiting quietly",
  prowl: "Prowling toward a tree",
  tired: "Catching breath",
  hug: "Hugging a blue blob",
  rest: "Resting after a hug",
  bud: "Budding a copy",
  fade: "Fading away",
};

/** Actions that run to completion; everything else re-decides on a short cadence. */
const LOCKED: ReadonlySet<Action> = new Set(["eat", "hugged", "bud", "hug", "rest", "fade", "startled", "tired"]);
/** Seconds a red can sprint after one blue before it has to give up. */
export const CHASE_LIMIT = 4;
export const TIRED_TIME = 1.6;
export const CHASE_BOOST = 1.2;
export const FLEE_BOOST = 1.35;
export const PROWL_CHANCE = 0.1;
/** Blues munching under a canopy, or waiting beside one, are only spotted from these fractions of a red's vision. */
export const SHADE_EATING = 0.55;
export const SHADE_WAITING = 0.55;
/** Blues notice reds within this fraction of their vision. */
export const FEAR_FRACTION = 0.65;
/** Reds only bud when at most RED_ROOM_MAX other reds are within RED_ROOM. */
export const RED_ROOM = 4;
export const RED_ROOM_MAX = 2;
export const RED_ENERGY_CAP = 1.6;
export const RED_SPACING = 2.5;

export type SlotState = "ripe" | "eaten" | "waiting" | "growing" | "off";

export interface Slot {
  state: SlotState;
  growth: number;
  timer: number;
  eater: number;
  rate: number;
  angle: number;
  lift: number;
}

export interface Tree {
  id: number;
  x: number;
  z: number;
  canopy: number;
  height: number;
  slots: Slot[];
  ripe: number;
  claims: number;
  lastEaten: number;
  eatenTotal: number;
  seed: number;
}

export interface Blob {
  id: number;
  group: Group;
  name: string;
  x: number;
  z: number;
  px: number;
  pz: number;
  heading: number;
  pheading: number;
